#!/bin/bash
# Generate vendor/lge/vfp makefiles from proprietary-blobs.txt
set -e
cd "$(dirname "$0")"
VENDOR=lge; DEVICE=vfp
OUT=../../../vendor/$VENDOR/$DEVICE
HDR="# Copyright (C) 2026 The LineageOS Project
#
# Licensed under the Apache License, Version 2.0 (the \"License\");
# you may not use this file except in compliance with the License.
#
# This file is generated by device/$VENDOR/$DEVICE/setup-makefiles.sh"

{
echo "$HDR"; echo
echo "PRODUCT_COPY_FILES += \\"
for line in $(grep -vE '^#|^$' proprietary-blobs.txt); do
    dst=${line#*:}
    echo "    vendor/$VENDOR/$DEVICE/proprietary/$dst:system/$dst \\"
done
echo
} > $OUT/$DEVICE-vendor-blobs.mk

{
echo "$HDR"; echo
echo "\$(call inherit-product, vendor/$VENDOR/$DEVICE/$DEVICE-vendor-blobs.mk)"
} > $OUT/$DEVICE-vendor.mk

{ echo "$HDR"; echo; echo "USE_CAMERA_STUB := false"; } > $OUT/BoardConfigVendor.mk
